package com.ruoyi.majorpilot.operations;

import com.fasterxml.jackson.databind.*;
import com.ruoyi.majorpilot.shared.*;
import java.sql.Timestamp;
import java.time.Instant;
import java.util.*;
import java.util.function.Function;
import org.springframework.context.annotation.Profile;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;
import static com.ruoyi.majorpilot.operations.OperationsDtos.*;

@Service @Profile({"local","pilot"})
public class OperationsService {
    final JdbcTemplate db;final TransactionTemplate tx;final ObjectMapper mapper;final OperationsAudit audit;private final IdempotencyService idem;private final Secrets secrets;
    public OperationsService(JdbcTemplate db,TransactionTemplate tx,ObjectMapper mapper,OperationsAudit audit,IdempotencyService idem,Secrets secrets){this.db=db;this.tx=tx;this.mapper=mapper;this.audit=audit;this.idem=idem;this.secrets=secrets;}
    static long n(Map<String,Object> r,String k){return ((Number)r.get(k)).longValue();}
    static Long nullable(Map<String,Object> r,String k){return r.get(k)==null?null:n(r,k);}
    static String s(Map<String,Object> r,String k){return (String)r.get(k);}
    static Instant time(Map<String,Object> r,String k){return r.get(k)==null?null:DbTimes.instant(r.get(k));}
    String alias(String id){return "Student-"+secrets.hmac("operator-alias",id).substring(0,12);}
    static ApiException missing(){return new ApiException(404,"RESOURCE_NOT_FOUND");}
    private static void readableStudent(String status){if(Set.of("DELETION_PENDING","DELETED").contains(status))throw missing();}
    JsonNode json(Object value){try{return value==null?mapper.nullNode():mapper.readTree(value.toString());}catch(Exception bad){throw new IllegalStateException("Stored projection invalid");}}
    static final class Where {
        final StringBuilder sql=new StringBuilder(" WHERE 1=1");final List<Object> args=new ArrayList<>();
        Where add(String expression,Object... values){sql.append(" AND ").append(expression);args.addAll(Arrays.asList(values));return this;}
        Where optional(String expression,Object value){return value==null?this:add(expression,value);}
        Where period(String column,Filters f){return add(column+">=? AND "+column+"<?",Timestamp.from(f.from()),Timestamp.from(f.to()));}
        Object[] params(){return args.toArray();}
    }
    private <T> Page<T> page(String from,String select,Where where,OperationsQuery query,String order,Function<Map<String,Object>,T> projection){
        long count=db.queryForObject("SELECT COUNT(*) "+from+where.sql,Long.class,where.params());
        var args=new ArrayList<>(where.args);args.add(query.pageSize());args.add(query.offset());
        return new Page<>(db.queryForList("SELECT "+select+" "+from+where.sql+" ORDER BY "+order+" LIMIT ? OFFSET ?",args.toArray()).stream().map(projection).toList(),count);
    }
    static final String RUN_FROM="FROM mp_experience_run r JOIN mp_student_account a ON a.id=r.student_id LEFT JOIN mp_major m ON m.id=r.major_id LEFT JOIN mp_task_version t ON t.id=r.task_version_id LEFT JOIN mp_decision_profile p ON p.id=r.decision_profile_id LEFT JOIN mp_recommendation rec ON rec.id=r.source_recommendation_id LEFT JOIN mp_experience_run origin ON origin.id=r.origin_run_id";
    static final String RUN_SELECT="r.*,a.public_id AS student_public_id,m.code AS major_code,t.public_id AS task_public_id,t.version_code,origin.public_id AS origin_public_id";
    Where runWhere(OperationsQuery q,boolean export){var w=new Where().period(export?"r.started_at":"r.created_at",q.filters()).add("r.created_at<=?",Timestamp.from(q.filters().asOf()));runFilters(w,q.filters());w.optional("r.status=?",q.status()).optional("a.public_id=?",q.studentId()).optional("r.run_mode=?",q.runMode());if(export)eligible(w,"a").add("r.content_kind='MAJOR' AND r.run_mode='STANDARD'");else exclusion(w,q.exclusionCode());return w;}
    static void runFilters(Where w,Filters f){w.optional("m.code=?",f.majorCode()).optional("t.public_id=?",f.taskVersionId()).optional("p.questionnaire_version=?",f.questionnaireVersion()).optional("rec.rule_version=?",f.recommendationRuleVersion());}
    static Where eligible(Where w,String alias){return w.add(alias+".analytics_exclusion_code IS NULL AND "+alias+".status NOT IN ('DELETION_PENDING','DELETED')");}
    private static void exclusion(Where w,String code){if(code==null)return;if(code.equals("NONE"))w.add("a.analytics_exclusion_code IS NULL");else w.add("a.analytics_exclusion_code=?",code);}
    RunRow run(Map<String,Object> r){String student=s(r,"student_public_id");return new RunRow(s(r,"public_id"),student,alias(student),s(r,"content_kind"),s(r,"run_mode"),s(r,"major_code"),s(r,"task_public_id"),s(r,"version_code"),s(r,"status"),s(r,"current_step_key"),n(r,"row_version"),(int)n(r,"attempt_no"),s(r,"origin_public_id"),time(r,"started_at"),time(r,"closed_at"),time(r,"last_activity_at"));}
    public Page<RunRow> runs(long operator,OperationsQuery q){audit.operator(operator,false,false);return tx.execute(t->page(RUN_FROM,RUN_SELECT,runWhere(q,false),q,q.order(Map.of("startedAt","r.started_at","lastActivityAt","r.last_activity_at","status","r.status","createdAt","r.created_at"),"lastActivityAt")+",r.id DESC",this::run));}
    static final String STUDENT_SELECT="a.*,(SELECT COUNT(*) FROM mp_decision_profile p WHERE p.student_id=a.id AND p.profile_version_no>0) AS profile_count,(SELECT COUNT(DISTINCT major_id) FROM mp_experience_run r WHERE r.student_id=a.id AND r.run_mode='STANDARD' AND r.content_kind='MAJOR' AND r.started_at IS NOT NULL) AS started_count,(SELECT COUNT(DISTINCT major_id) FROM mp_experience_run r WHERE r.student_id=a.id AND r.run_mode='STANDARD' AND r.content_kind='MAJOR' AND r.status='CLOSED') AS closed_count";
    Where studentWhere(OperationsQuery q,boolean export){var w=new Where().period("a.created_at",q.filters()).optional("a.status=?",q.status()).optional("a.public_id=?",q.studentId());if(export)eligible(w,"a");else exclusion(w,q.exclusionCode());var f=q.filters();if(f.majorCode()!=null||f.taskVersionId()!=null||f.questionnaireVersion()!=null||f.recommendationRuleVersion()!=null){var scope=new Where().add("r.student_id=a.id AND r.content_kind='MAJOR' AND r.run_mode='STANDARD' AND r.started_at<=?",Timestamp.from(f.asOf()));runFilters(scope,f);w.add("EXISTS(SELECT 1 FROM mp_experience_run r LEFT JOIN mp_major m ON m.id=r.major_id LEFT JOIN mp_task_version t ON t.id=r.task_version_id LEFT JOIN mp_decision_profile p ON p.id=r.decision_profile_id LEFT JOIN mp_recommendation rec ON rec.id=r.source_recommendation_id"+scope.sql+")",scope.params());}return w;}
    StudentRow student(Map<String,Object> r){String id=s(r,"public_id");return new StudentRow(id,alias(id),s(r,"status"),s(r,"analytics_exclusion_code"),n(r,"row_version"),time(r,"created_at"),time(r,"email_verified_at"),time(r,"last_login_at"),n(r,"profile_count"),n(r,"started_count"),n(r,"closed_count"));}
    public Page<StudentRow> students(long operator,OperationsQuery q){audit.operator(operator,false,false);return tx.execute(t->page("FROM mp_student_account a",STUDENT_SELECT,studentWhere(q,false),q,q.order(Map.of("createdAt","a.created_at","lastLoginAt","a.last_login_at","status","a.status"),"createdAt")+",a.id DESC",this::student));}
    private Map<String,Object> studentOwned(String id,boolean lock){var rows=db.queryForList("SELECT "+STUDENT_SELECT+" FROM mp_student_account a WHERE a.public_id=?"+(lock?" FOR UPDATE":""),id);if(rows.isEmpty())throw missing();return rows.getFirst();}
    public StudentDetail studentDetail(long operator,String id){audit.operator(operator,false,false);return tx.execute(t->{var r=studentOwned(id,false);var consents=db.queryForList("SELECT document_type,document_version,decision,decided_at FROM mp_consent_record WHERE student_id=? ORDER BY id DESC LIMIT 100",n(r,"id")).stream().map(c->new ConsentSummary(s(c,"document_type"),s(c,"document_version"),s(c,"decision"),time(c,"decided_at"))).toList();var profiles=db.queryForList("SELECT public_id,questionnaire_version,profile_version_no,status,submitted_at FROM mp_decision_profile WHERE student_id=? AND profile_version_no>0 ORDER BY profile_version_no DESC LIMIT 100",n(r,"id")).stream().map(p->new ProfileSummary(s(p,"public_id"),s(p,"questionnaire_version"),n(p,"profile_version_no"),s(p,"status"),time(p,"submitted_at"))).toList();return new StudentDetail(student(r),new StudentDetails(consents,profiles,100));});}
    public StudentRow exclusion(long operator,String id,String key,Exclusion input,String request){audit.analyticsOperator(operator,false);var account=studentOwned(id,false);return tx.execute(t->{studentOwned(id,true);audit.analyticsOperator(operator,true);return idem.executeOperatorScoped(new IdempotencyService.Owner(n(account,"id"),null,"operator:"+operator),"PATCH","/api/admin/v1/majorpilot/students/"+id+"/analytics-exclusion",key,input,StudentRow.class,()->{var row=studentOwned(id,true);audit.analyticsOperator(operator,true);if(input.expectedRevision()==null||input.expectedRevision()!=n(row,"row_version"))throw new ApiException(409,"STUDENT_REVISION_CONFLICT",Map.of("currentRevision",n(row,"row_version")));if(input.exclusionCode()==null||!Set.of("NONE","TEST","BOT").contains(input.exclusionCode())||input.reason()==null||input.reason().isBlank()||input.reason().length()<10||input.reason().length()>500)throw OperationsQuery.invalid();String after=input.exclusionCode().equals("NONE")?null:input.exclusionCode();db.update("UPDATE mp_student_account SET analytics_exclusion_code=?,row_version=row_version+1 WHERE id=?",after,n(row,"id"));audit.write(operator,n(row,"id"),"ANALYTICS_EXCLUSION","STUDENT",id,input.exclusionCode(),input.reason(),Map.of("exclusionCode",Objects.toString(row.get("analytics_exclusion_code"),"NONE")),Map.of("exclusionCode",input.exclusionCode()),request);return student(studentOwned(id,false));}).data();});}
    private Map<String,Object> runOwned(String id){var rows=db.queryForList("SELECT "+RUN_SELECT+" "+RUN_FROM+" WHERE r.public_id=?",id);if(rows.isEmpty())throw missing();return rows.getFirst();}
    public RunDetail runDetail(long operator,String id){audit.operator(operator,false,false);return tx.execute(t->{var r=runOwned(id);var steps=db.queryForList("SELECT step_key,status,current_revision,completed_at FROM mp_step_state WHERE experience_run_id=? ORDER BY id",n(r,"id")).stream().map(s->new StepSummary(s(s,"step_key"),s(s,"status"),n(s,"current_revision"),time(s,"completed_at"))).toList();var executions=db.queryForList("SELECT operation_key,status,trust_level,error_code,COUNT(*) AS count FROM mp_execution_record WHERE experience_run_id=? GROUP BY operation_key,status,trust_level,error_code",n(r,"id")).stream().map(e->new ExecutionSummary(s(e,"operation_key"),s(e,"status"),s(e,"trust_level"),s(e,"error_code"),n(e,"count"))).toList();return new RunDetail(run(r),new RunDetails(steps,executions));});}
    public SensitiveStudent sensitiveStudent(long operator,String id,SensitiveView input,String request){OperationsAudit.purpose(input.purpose(),input.reason());return tx.execute(t->{var a=studentOwned(id,true);readableStudent(s(a,"status"));audit.operator(operator,false,true);audit.write(operator,n(a,"id"),"STUDENT_SENSITIVE_READ","STUDENT",id,input.purpose(),input.reason(),Map.of(),Map.of("fields",List.of("email")),request);return new SensitiveStudent(id,s(a,"email_display"));});}
    public SensitiveRun sensitiveRun(long operator,String id,SensitiveView input,String request){OperationsAudit.purpose(input.purpose(),input.reason());return tx.execute(t->{var r=runOwned(id);readableStudent(db.queryForObject("SELECT status FROM mp_student_account WHERE id=? FOR UPDATE",String.class,n(r,"student_id")));audit.operator(operator,false,true);var answers=db.queryForList("SELECT s.step_key,r.revision_no,r.response_json,r.received_at FROM mp_step_response_revision r JOIN mp_step_state s ON s.id=r.step_state_id WHERE s.experience_run_id=? ORDER BY s.id,r.revision_no LIMIT 10001",n(r,"id"));if(answers.size()>10000)throw new ApiException(422,"SENSITIVE_SCOPE_TOO_LARGE");var output=answers.stream().map(a->new ResponseRevision(s(a,"step_key"),n(a,"revision_no"),json(a.get("response_json")),time(a,"received_at"))).toList();var reflection=db.queryForList("SELECT draft_json,question_set_version,status FROM mp_reflection WHERE experience_run_id=?",n(r,"id"));audit.write(operator,n(r,"student_id"),"EXPERIENCE_SENSITIVE_READ","EXPERIENCE_RUN",id,input.purpose(),input.reason(),Map.of(),Map.of("revisionCount",answers.size()),request);return new SensitiveRun(id,output,reflection.isEmpty()?mapper.nullNode():json(reflection.getFirst().get("draft_json")));});}
    static final String REPORT_FROM="FROM mp_report r JOIN mp_student_account a ON a.id=r.student_id LEFT JOIN mp_major m ON m.id=r.major_id LEFT JOIN mp_report_version v ON v.id=r.current_version_id LEFT JOIN mp_experience_run er ON er.id=r.experience_run_id LEFT JOIN mp_task_version t ON t.id=er.task_version_id LEFT JOIN mp_decision_profile p ON p.id=er.decision_profile_id LEFT JOIN mp_recommendation rec ON rec.id=er.source_recommendation_id";
    static final String REPORT_SELECT="r.*,a.public_id AS student_public_id,m.code AS major_code,v.public_id AS version_public_id,v.version_no,v.generation_mode,v.failure_code";
    Where reportWhere(OperationsQuery q,boolean export){var w=new Where().period(export?"r.first_ready_at":"r.requested_at",q.filters()).optional("r.status=?",q.status()).optional("a.public_id=?",q.studentId()).optional("r.report_type=?",q.filters().reportType());if(OperationsQuery.hasRunDimensions(q.filters()))w.add("r.report_type='EXPERIENCE'");runFilters(w,q.filters());if(export)eligible(w,"a");else exclusion(w,q.exclusionCode());return w;}
    ReportRow report(Map<String,Object> r){String student=s(r,"student_public_id");return new ReportRow(s(r,"public_id"),student,alias(student),s(r,"report_type"),s(r,"major_code"),s(r,"status"),s(r,"version_public_id"),nullable(r,"version_no"),s(r,"generation_mode"),s(r,"failure_code"),time(r,"requested_at"),time(r,"ready_at"),time(r,"first_ready_at"),n(r,"row_version"));}
    public ReportPage reports(long operator,OperationsQuery q){audit.operator(operator,false,false);var page=tx.execute(t->page(REPORT_FROM,REPORT_SELECT,reportWhere(q,false),q,q.order(Map.of("requestedAt","r.requested_at","firstReadyAt","r.first_ready_at","status","r.status"),"requestedAt")+",r.id DESC",this::report));return new ReportPage(page.rows(),page.total(),OperationsQuery.reportScope(q.filters()));}
    public Page<TaskRow> tasks(long operator,OperationsQuery q){audit.operator(operator,false,false);var where=new Where().optional("t.status=?",q.status()).optional("m.code=?",q.filters().majorCode()).optional("t.public_id=?",q.filters().taskVersionId());return tx.execute(tx->page("FROM mp_task_version t LEFT JOIN mp_major m ON m.id=t.major_id","t.*,m.code AS major_code",where,q,q.order(Map.of("createdAt","t.created_at","publishedAt","t.published_at","status","t.status"),"createdAt")+",t.id DESC",r->new TaskRow(s(r,"public_id"),s(r,"content_kind"),s(r,"major_code"),s(r,"demo_key"),s(r,"version_code"),json(r.get("manifest_json")).path("title").asText(),s(r,"status"),s(r,"manifest_sha256"),s(r,"data_sha256"),nullable(r,"reviewed_by_operator_id"),time(r,"published_at"),time(r,"retired_at"),n(r,"row_version"))));}
    public TaskReviewContext taskReviewContext(long operator,String id){audit.operator(operator,false,false);return tx.execute(t->{var rows=db.queryForList("SELECT public_id,manifest_path,manifest_json,status,row_version FROM mp_task_version WHERE public_id=?",id);if(rows.isEmpty())throw missing();var row=rows.getFirst();return reviewContext(row,json(row.get("manifest_json")));});}
    static TaskReviewContext reviewContext(Map<String,Object> row,JsonNode manifest){String path=s(row,"manifest_path");if(path==null||!path.matches("[A-Za-z0-9][A-Za-z0-9._/-]{0,240}/manifest\\.json")||Arrays.stream(path.split("/",-1)).anyMatch(p->p.isEmpty()||p.equals(".")||p.equals("..")))throw new ApiException(503,"CONTENT_INTEGRITY_FAILED");var keys=manifest.at("/review/checkKeys");if(!keys.isArray()||keys.isEmpty()||keys.size()>100)throw new ApiException(503,"CONTENT_INTEGRITY_FAILED");var ordered=new ArrayList<String>();for(var key:keys){if(!key.isTextual()||!key.asText().matches("[A-Z][A-Z0-9_]{0,79}")||ordered.contains(key.asText()))throw new ApiException(503,"CONTENT_INTEGRITY_FAILED");ordered.add(key.asText());}return new TaskReviewContext(s(row,"public_id"),path,List.copyOf(ordered),s(row,"status"),n(row,"row_version"));}
    public Page<AuditRow> audits(long operator,OperationsQuery q){audit.operator(operator,false,false);var where=new Where().period("x.occurred_at",q.filters()).optional("a.public_id=?",q.studentId());return tx.execute(t->page("FROM mp_sensitive_audit x LEFT JOIN mp_student_account a ON a.id=x.owner_student_id","x.*,a.public_id AS student_public_id",where,q,q.order(Map.of("occurredAt","x.occurred_at","actionCode","x.action_code"),"occurredAt")+",x.id DESC",r->new AuditRow(s(r,"public_id"),n(r,"operator_id"),s(r,"action_code"),s(r,"target_type"),s(r,"target_public_id"),r.get("student_public_id")==null?null:alias(s(r,"student_public_id")),s(r,"reason_code"),time(r,"occurred_at"))));}
}
